    for r in range(H):
        for c in range(W):
            if g[r,c] and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)): 
                        p=(a+da,b+db)
                        if 0<=p[0]<H and 0<=p[1]<W and g[p]==g[r,c] and not seen[p]:
                            seen[p]=True; st.append(p)
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                sub=np.array([[int(g[a][b]) for b in range(cs[0],cs[-1]+1)] for a in range(rs[0],rs[-1]+1)])
                out.append({'color':g[r,c],'cells':cells,'sub':sub})
