        while st:
            a,b=st.pop()
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(a+da,b+db)
                if q in {(p,q_) for p,q_,_ in pts} and q not in used:
                    used.add(q); comp.add(q); cells_comp.append(int(g[q[0],q[1]]))
        ns.append({'cells':sorted(comp),'colors':set(cells_comp),'rs':min(p[0] for p in comp),'cs':min(p[1] for p in comp)})
    HZ=len(Z); NZ=len(ns)
    res=None
