            rc_=min(p[0] for p in Z[zi]); cc_=min(p[1] for p in Z[zi])
            dr=rc_-rs; dc=cc_-cs_
            cov=sum(1 for p in s['cells'] if (p[0]+dr,p[1]+dc) in Z[zi])
            if cov<len(s['cells']): ok=False; break
            placed.append((idx,zi,(dr,dc)))
