G=load()

def components(g, color):
    H,W=g.shape; vis=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if g[r,c]==color and not vis[r,c]:
                st=[(r,c)];vis[r,c]=True; comp=set()
                while st:
                    a,b=st.pop();comp.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(a+da,b+db)
                        if 0<=q[0]<H and 0<=q[1]<W and g[q[0],q[1]]==color and not vis[q[0],q[1]]:
                            vis[q[0],q[1]]=True; st.append(q)
                out.append(comp)
    return out

def solve(g):
    g=np.array(g); H,W=g.shape
    vals={int(g[r,c]) for r in range(H) for c in range(W)}-{0}
    bg=Counter(int(x) for row in g for x in row).most_common(1)[0][0]
    # frame = largest component of the frame color (the rectangle border structure)
    big=None
    for col in [int(c) for c in vals]:
        for comp in components(g,col):
            if big is None or len(comp)>len(big): big=comp
    r0=min(p[0] for p in big); r1=max(p[0] for p in big)
    c0=min(p[1] for p in big); c1=max(p[1] for p in big)
    hf, wf=r1-r0+1, c1-c0+1
    zeros=[(i,j) for i in range(hf) for j in range(wf) if g[r0+i,c0+j]==0]
    Z=[]; seen=np.zeros((hf,wf),bool)
    for (i,j) in sorted(zeros):
        if seen[i,j]: continue
        st=[(i,j)];seen[i,j]=True; comp=set()
        while st:
            a,b=st.pop();comp.add((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(a+da,b+db)
                if q in {(a,b) for a,b in zeros} and q not in comp and q[0]<hf and q[1]<wf:
                    if seen[q[0],q[1]]: continue
                    seen[q[0],q[1]]=True; st.append(q); comp.add(q)
        Z.append(comp)
    # noise = connected comps of non-bg colors outside frame bbox
    ns=[]
    used={(r,c) for r in range(H) for c in range(W) if r<r0 or r>r1 or c<c0 or c>c1 and int(g[r,c])!=bg}
    for (r,c) in list(used):
        if (r,c) in [(p,q) for p,q in []] or False: pass
    pts=[(r,c) for r in range(H) for c in range(W) if (r<r0 or r>r1 or c<c0 or c>c1) and int(g[r,c])!=bg]
    seenP=np.zeros((H,W),bool); ns=[]
    for (r,c) in pts:
        if seenP[r,c]: continue
        st=[(r,c)];seenP[r,c]=True; comp=set()
        while st:
            a,b=st.pop();comp.add((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(a+da,b+db)
                if q in set(pts) and not seenP[q[0],q[1]]:
                    seenP[q[0],q[1]]=True; st.append(q); comp.add(q)
        col=int(g[r,c])
        rs=min(p[0] for p in comp); cs_=min(p[1] for p in comp)
        shape=[(p[0]-rs,p[1]-cs_) for p in comp]
        ns.append({'cells':list(comp),'colors':[col],'shape':shape,'r0':rs,'c0':cs_})
    m=len(Z); n=len(ns)
    best=None;bestcov=-1
    for perm in permutations(range(m)):
        ok=True; cov=0
        for s,z_i in zip(ns,perm):
            sz_i=Z[z_i]
            rc_=min(p[0] for p in sz_i); cc_=min(p[1] for p in sz_i)
            dr=rc_-s['r0']; dc=cc_-s['c0']
            hit=sum(1 for p in s['cells'] if (p[0]+dr,p[1]+dc) in sz_i)
            if hit<s['cells'].__len__(): ok=False; break
            cov+=hit
        if ok and cov>=bestcov: bestcov=cov; best=perm
    out=[[int(g[r0+i,c0+j]) for j in range(wf)] for i in range(hf)]
    for idx,z_i in enumerate(best):
        s=ns[idx]; col=s['colors'][0]
        z_i=z_i
        sz_i=Z[z_i]; rc_=min(p[0] for p in sz_i); cc_=min(p[1] for p in sz_i)
        dr=rc_-s['r0']; dc=cc_-s['c0']
        for p in s['cells']:
            out[p[0]+dr][p[1]+dc]=col
    placed=set(best)
    for zi in range(m):
        if zi not in placed:
            for q in Z[zi]: out[q[0]][q[1]]=bg
    return [[int(x) for x in row] for row in out]

